create type public.utility_billing_mode as enum ('ACTUAL_BILL','FIXED','INCLUDED');
create type public.utility_distribution_method as enum ('BY_RESIDENT','BY_ROOM','MANUAL');
create type public.utility_bill_status as enum ('DRAFT','CONFIRMED','CHARGED','CANCELLED');
create table public.property_utility_configs(id uuid primary key default gen_random_uuid(),administration_id uuid not null references public.administrations(id) on delete cascade,property_id uuid not null references public.properties(id) on delete cascade,utility_code text not null,billing_mode public.utility_billing_mode not null,distribution_method public.utility_distribution_method,fixed_amount numeric(14,2),is_enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(property_id,utility_code),check ((billing_mode='ACTUAL_BILL' and distribution_method is not null and fixed_amount is null) or (billing_mode='FIXED' and fixed_amount is not null and fixed_amount>=0 and distribution_method is null) or (billing_mode='INCLUDED' and fixed_amount is null and distribution_method is null)));
create table public.utility_bills(id uuid primary key default gen_random_uuid(),administration_id uuid not null references public.administrations(id) on delete cascade,property_id uuid not null references public.properties(id) on delete cascade,utility_config_id uuid not null references public.property_utility_configs(id) on delete restrict,period_start date not null,period_end date not null,due_date date,amount numeric(14,2) not null check(amount>=0),status public.utility_bill_status not null default 'DRAFT',confirmed_at timestamptz,created_at timestamptz not null default now(),unique(utility_config_id,period_start,period_end),check(period_end>=period_start));
create table public.utility_allocations(id uuid primary key default gen_random_uuid(),administration_id uuid not null references public.administrations(id) on delete cascade,utility_bill_id uuid not null references public.utility_bills(id) on delete cascade,rental_relationship_id uuid not null references public.rental_relationships(id) on delete restrict,amount numeric(14,2) not null check(amount>=0),charge_id uuid references public.charges(id) on delete set null,created_at timestamptz not null default now(),unique(utility_bill_id,rental_relationship_id));
create index property_utility_configs_admin_idx on public.property_utility_configs(administration_id); create index utility_bills_admin_idx on public.utility_bills(administration_id); create index utility_allocations_relationship_idx on public.utility_allocations(rental_relationship_id);
alter table public.property_utility_configs enable row level security; alter table public.utility_bills enable row level security; alter table public.utility_allocations enable row level security;
grant select on public.property_utility_configs,public.utility_bills,public.utility_allocations to authenticated; revoke insert,update,delete on public.property_utility_configs,public.utility_bills,public.utility_allocations from anon,authenticated;
create policy utility_configs_select on public.property_utility_configs for select to authenticated using(public.is_administration_member(administration_id)); create policy utility_bills_select on public.utility_bills for select to authenticated using(public.is_administration_member(administration_id)); create policy utility_allocations_select on public.utility_allocations for select to authenticated using(public.is_administration_member(administration_id) or public.can_view_relationship(rental_relationship_id));
create trigger property_utility_configs_updated before update on public.property_utility_configs for each row execute function public.set_updated_at();
create or replace function public.configure_property_utility(p_property_id uuid,p_utility_code text,p_billing_mode public.utility_billing_mode,p_distribution_method public.utility_distribution_method default null,p_fixed_amount numeric default null) returns public.property_utility_configs language plpgsql security definer set search_path='' as $$ declare p public.properties; c public.property_utility_configs; begin select * into p from public.properties where id=p_property_id; if not found then raise exception 'PROPERTY_NOT_FOUND'; end if; if public.can_manage_administration(p.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if p.rental_mode<>'BY_ROOMS' then raise exception 'UTILITY_ALLOCATION_REQUIRES_ROOM_RENTAL'; end if; insert into public.property_utility_configs(administration_id,property_id,utility_code,billing_mode,distribution_method,fixed_amount) values(p.administration_id,p.id,upper(btrim(p_utility_code)),p_billing_mode,p_distribution_method,p_fixed_amount) on conflict(property_id,utility_code) do update set billing_mode=excluded.billing_mode,distribution_method=excluded.distribution_method,fixed_amount=excluded.fixed_amount,is_enabled=true returning * into c; return c; end $$;
revoke all on function public.configure_property_utility(uuid,text,public.utility_billing_mode,public.utility_distribution_method,numeric) from public,anon; grant execute on function public.configure_property_utility(uuid,text,public.utility_billing_mode,public.utility_distribution_method,numeric) to authenticated,service_role;